CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, phone VARCHAR(255) NOT NULL DEFAULT '', role VARCHAR(255) NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')), active BIGINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE sessions(token_hash VARCHAR(255) PRIMARY KEY, user_id BIGINT, csrf VARCHAR(255) NOT NULL, expires_at BIGINT NOT NULL,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE password_resets(token_hash VARCHAR(255) PRIMARY KEY, user_id BIGINT NOT NULL, expires_at BIGINT NOT NULL,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE addresses(id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, name VARCHAR(255) NOT NULL, phone VARCHAR(255) NOT NULL, street VARCHAR(255) NOT NULL, city VARCHAR(255) NOT NULL, county VARCHAR(255) NOT NULL, postal_code VARCHAR(255) NOT NULL DEFAULT '',FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE categories(id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, parent_id BIGINT, description TEXT NOT NULL DEFAULT (''), image VARCHAR(255) NOT NULL DEFAULT '', sort_order BIGINT NOT NULL DEFAULT 0, seo TEXT NOT NULL DEFAULT ('{}'),FOREIGN KEY (parent_id) REFERENCES categories(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE products(id BIGINT PRIMARY KEY AUTO_INCREMENT, source_id VARCHAR(255) UNIQUE, sku VARCHAR(255), name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, status VARCHAR(255) NOT NULL DEFAULT 'publish' CHECK(status IN ('publish','draft','archived')), price_cents BIGINT CHECK(price_cents >= 0), regular_price_cents BIGINT CHECK(regular_price_cents >= 0), sale_price_cents BIGINT CHECK(sale_price_cents >= 0), stock BIGINT CHECK(stock >= 0), stock_status VARCHAR(255) NOT NULL DEFAULT 'instock' CHECK(stock_status IN ('instock','outofstock')), manage_stock BIGINT NOT NULL DEFAULT 0, featured BIGINT NOT NULL DEFAULT 0, description TEXT NOT NULL DEFAULT (''), short_description TEXT NOT NULL DEFAULT (''), tax_status VARCHAR(255) NOT NULL DEFAULT '', tax_class VARCHAR(255) NOT NULL DEFAULT '', source_fields TEXT NOT NULL DEFAULT ('{}'), seo TEXT NOT NULL DEFAULT ('{}'), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE product_categories(product_id BIGINT NOT NULL, category_id BIGINT NOT NULL, PRIMARY KEY(product_id,category_id),FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE product_images(id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, url VARCHAR(255) NOT NULL, alt VARCHAR(255) NOT NULL DEFAULT '', sort_order BIGINT NOT NULL DEFAULT 0, original_url VARCHAR(255) NOT NULL DEFAULT '',FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE stock_movements(id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, delta BIGINT NOT NULL, balance BIGINT, reason VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE favorites(user_id BIGINT NOT NULL, product_id BIGINT NOT NULL, PRIMARY KEY(user_id,product_id),FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE cart_items(session_hash VARCHAR(255) NOT NULL, product_id BIGINT NOT NULL, quantity BIGINT NOT NULL CHECK(quantity BETWEEN 1 AND 99), PRIMARY KEY(session_hash,product_id),FOREIGN KEY (product_id) REFERENCES products(id),FOREIGN KEY (session_hash) REFERENCES sessions(token_hash) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE customers(id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, phone VARCHAR(255) NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT ('{}'), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE discounts(id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(255) NOT NULL UNIQUE, type VARCHAR(255) NOT NULL CHECK(type IN ('percent','fixed')), value BIGINT NOT NULL CHECK(value > 0), min_cents BIGINT NOT NULL DEFAULT 0, max_uses BIGINT, uses BIGINT NOT NULL DEFAULT 0, expires_at VARCHAR(255), active BIGINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE shipping_methods(id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, price_cents BIGINT NOT NULL CHECK(price_cents >= 0), free_threshold_cents BIGINT, zones VARCHAR(255) NOT NULL DEFAULT '', enabled BIGINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE payment_methods(code VARCHAR(255) PRIMARY KEY, name VARCHAR(255) NOT NULL, enabled BIGINT NOT NULL DEFAULT 0, mode VARCHAR(255) NOT NULL DEFAULT 'disabled') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE orders(id BIGINT PRIMARY KEY AUTO_INCREMENT, number VARCHAR(255) UNIQUE, customer_id BIGINT NOT NULL, user_id BIGINT, session_hash VARCHAR(255) NOT NULL, idempotency_key VARCHAR(255) NOT NULL, status VARCHAR(255) NOT NULL DEFAULT 'received', payment_method VARCHAR(255) NOT NULL, payment_status VARCHAR(255) NOT NULL DEFAULT 'unpaid', shipping_method VARCHAR(255) NOT NULL, shipping_address TEXT NOT NULL, subtotal_cents BIGINT NOT NULL, discount_cents BIGINT NOT NULL DEFAULT 0, shipping_cents BIGINT NOT NULL, total_cents BIGINT NOT NULL, coupon VARCHAR(255) NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT (''), admin_notes TEXT NOT NULL DEFAULT (''), stock_restored BIGINT NOT NULL DEFAULT 0, access_token VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(session_hash,idempotency_key),FOREIGN KEY (customer_id) REFERENCES customers(id),FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE order_items(id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, product_id BIGINT, sku VARCHAR(255), name VARCHAR(255) NOT NULL, image VARCHAR(255) NOT NULL, quantity BIGINT NOT NULL, price_cents BIGINT NOT NULL, total_cents BIGINT NOT NULL,FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY (product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE order_status_history(id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, status VARCHAR(255) NOT NULL, note VARCHAR(255) NOT NULL DEFAULT '', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE pages(id BIGINT PRIMARY KEY AUTO_INCREMENT, slug VARCHAR(255) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, body TEXT NOT NULL DEFAULT (''), type VARCHAR(255) NOT NULL DEFAULT 'page', status VARCHAR(255) NOT NULL DEFAULT 'publish', image VARCHAR(255) NOT NULL DEFAULT '', seo TEXT NOT NULL DEFAULT ('{}')) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE media(id BIGINT PRIMARY KEY AUTO_INCREMENT, url VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, alt VARCHAR(255) NOT NULL DEFAULT '', type VARCHAR(255) NOT NULL DEFAULT 'image', uploaded BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE settings(`key` VARCHAR(255) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE newsletter(id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(255) NOT NULL UNIQUE, consent_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE messages(id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, phone VARCHAR(255) NOT NULL DEFAULT '', subject VARCHAR(255) NOT NULL DEFAULT '', body TEXT NOT NULL, status VARCHAR(255) NOT NULL DEFAULT 'new', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE reviews(id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, product_id BIGINT, name VARCHAR(255) NOT NULL, rating BIGINT NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, approved BIGINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id),FOREIGN KEY (product_id) REFERENCES products(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE outbox(id BIGINT PRIMARY KEY AUTO_INCREMENT, recipient VARCHAR(255) NOT NULL, subject VARCHAR(255) NOT NULL, body TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE INDEX idx_products_status ON products(status);
CREATE INDEX idx_products_sku ON products(sku);
CREATE INDEX idx_product_categories_category ON product_categories(category_id);
CREATE INDEX idx_orders_user_created ON orders(user_id,created_at);
CREATE INDEX idx_orders_status_created ON orders(status,created_at);
CREATE INDEX idx_stock_movements_product ON stock_movements(product_id);
CREATE INDEX idx_sessions_expires ON sessions(expires_at);
